/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* Designme shared core: tokens for Blueprint (default) and Soft (data-style="soft" on <html> or on any element around the components), light and dark (<html data-theme="dark">) */
:where([data-dm]) [hidden]{display:none!important}
/* hold(): an end state centred in the height its component had */
.dm-held{display:flex;flex-direction:column;justify-content:center}
/* the glide starts fast in both styles, so the field is on its way up before an opening list reaches the stage's edge */
.dm-glide{transform:translateY(var(--dm-gy,0px));transition:transform var(--dm-t) cubic-bezier(.22,1,.36,1)}
/* and a list that opens under a gliding field fades in a beat after it starts to move */
.dm-glide>.dm-csx-pop.dm-open{transition-delay:.08s}
.dm-glide>.dm-msc-pop.dm-open{transition-delay:.08s,.08s,.08s,0s}
/* Soft 2: one quiet surface per object, grey type for finished work, motion only on what is happening now */
:root,[data-style="soft"]{
  --dm-motion:soft;
  --dm-page:#f7f7f7; --dm-stage:#fafafa; --dm-surface:#ffffff; --dm-raised:#ffffff;
  --dm-fg:#171717; --dm-fg2:#525252; --dm-muted:#6a6a6a; --dm-faint:#c4c4c4; --dm-rail:#d4d4d4; --dm-line:#e8e8e8; --dm-field-line:#d4d4d4; --dm-line-strong:#858585; --dm-field-line-strong:#b3b3b3;
  --dm-chip:#f3f3f3; --dm-hover:#ebebeb; --dm-press:#e3e3e3; --dm-wash:#f9f9f9; --dm-row:#fafafa;
  --dm-soft:#ececec; --dm-soft-h:#e3e3e3; --dm-soft-ring:inset 0 0 0 1px rgba(0,0,0,.03),inset 0 1px 0 rgba(255,255,255,.7); --dm-dis:#a6a6a6;
  /* disabled: text and icons take --dm-dis; a control with a fill swaps it for --dm-dis-fill (Blueprint hatches it) */
  --dm-dis-fill:var(--dm-soft); --dm-dis-hatch:none;
  --dm-shadow-lift:0 0 0 1px rgba(0,0,0,.05),0 2px 4px rgba(0,0,0,.04),0 16px 32px -10px rgba(0,0,0,.16);
  /* the accent has three roles: --dm-accent fills (with --dm-on-accent on top, 4.5:1), --dm-accent-fg is text and icons in the accent
     (4.5:1 on the surface, and on the chips and tints it sits on) and --dm-accent-mark is lines, rings and chart marks (3:1). A
     light accent like lime keeps its fills and gets a darker mark and ink-coloured text on a light page */
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#0f5fd5; --dm-accent-mark:#116ff8; --dm-sel:color-mix(in srgb,var(--dm-accent) 6%,transparent);
  /* fields (text fields, textareas, search fields, dropdown triggers) have a dimmed grey edge, --dm-field-line, that steps up
     a little, to --dm-field-line-strong, while they have the focus. The keyboard's focus ring on every other control is 2px of
     a stronger grey (--dm-line-strong, as --dm-focus), as an outline offset 2px, or as a 2px box-shadow ring where an outline would be clipped. Never
     the accent and never black, and only from the keyboard (:focus-visible), so a click or a tap never shows one */
  --dm-focus:var(--dm-line-strong);
  --dm-ink:#1b1b1b; --dm-on-ink:#ffffff;
  --dm-ok:#0a7034; --dm-ok-bg:#cff5db; --dm-ok-mark:#4cbb17; --dm-warn:#9a4704; --dm-warn-bg:#ffe5b8; --dm-warn-mark:#f76700; --dm-bad:#b81d23; --dm-bad-bg:#ffe8e8;
  --dm-merge:#7c4cd4; --dm-merge-bg:#f2ecfd; --dm-add:#187633; --dm-del:#c7212c;
  --dm-pb:#1460d0; --dm-pb-bg:#eaf2ff; --dm-pl:#6b47d6; --dm-pl-bg:#f2edff; --dm-pm:#10754a; --dm-pm-bg:#e7f8f0; --dm-pp:#994c0b; --dm-pp-bg:#fff2e6;
  --dm-pr:#bf314d; --dm-pr-bg:#ffeef1; --dm-py:#856404; --dm-py-bg:#fffae3; --dm-pk:#b92e75; --dm-pk-bg:#fff0f7; --dm-pt:#0e747d; --dm-pt-bg:#e6f9fa;
  /* avatars have colours of their own, the same in every style and theme: a bright fill and the initials' ink on it (4.5:1,
     APCA Lc 60). Blue, violet, red and pink are deep enough for white; green, teal, yellow and orange are too light for white
     and take a dark ink of their own hue. An avatar given one of these, var(--dm-av-l), takes its ink, var(--dm-av-l-ink), on its own */
  --dm-av-b:#126fe6; --dm-av-b-ink:#ffffff; --dm-av-l:#834ff5; --dm-av-l-ink:#ffffff; --dm-av-r:#d73341; --dm-av-r-ink:#ffffff; --dm-av-k:#cf3288; --dm-av-k-ink:#ffffff;
  --dm-av-m:#27cf86; --dm-av-m-ink:#052616; --dm-av-t:#28c9d8; --dm-av-t-ink:#042428; --dm-av-y:#e9ac1a; --dm-av-y-ink:#2a1d03; --dm-av-p:#fda154; --dm-av-p-ink:#301804;
  --dm-ts:#2c6cb2; --dm-react:#0a738b;
  /* every raised surface carries its own hairline edge, so nothing needs a separate ring */
  /* soft, layered shadows: a hairline, a contact shadow and two wide, faint ones, with a faint highlight on the top edge */
  --dm-shadow:0 0 0 1px rgba(0,0,0,.03),0 1px 1px rgba(0,0,0,.025),0 2px 4px -1px rgba(0,0,0,.03),0 8px 16px -6px rgba(0,0,0,.05),0 20px 36px -14px rgba(0,0,0,.08),inset 0 1px 0 rgba(255,255,255,.75);
  --dm-shadow-pop:0 0 0 1px rgba(0,0,0,.035),0 1px 2px rgba(0,0,0,.03),0 4px 10px -4px rgba(0,0,0,.05),0 14px 28px -10px rgba(0,0,0,.08),0 32px 56px -24px rgba(0,0,0,.12),inset 0 1px 0 rgba(255,255,255,.75);
  --dm-shadow-toast:0 0 0 1px rgba(0,0,0,.03),0 4px 12px rgba(0,0,0,.08);
  --dm-hl:#fdeb9a; --dm-hl-ok:#d3f1df;
  /* Soft is plush: every corner is scaled by --dm-rk, and larger still where the browser draws true squircles (below) */
  --dm-rk:1.25;
  --dm-r-card:calc(16px * var(--dm-rk));
  /* spacing runs on a 4px scale, and corners on a small set of radii; values off the scale are still written out */
  --dm-s-1:4px; --dm-s-2:8px; --dm-s-3:12px; --dm-s-4:16px; --dm-s-5:20px; --dm-s-6:24px; --dm-s-8:32px; --dm-r-xs:calc(4px * var(--dm-rk)); --dm-r-lg:calc(20px * var(--dm-rk)); --dm-r-in:calc(12px * var(--dm-rk)); --dm-r-sm:calc(8px * var(--dm-rk)); --dm-r-pill:999px;
  /* fields and tags have slightly rounded corners, never pills: --dm-r-field for one-line fields and dropdown triggers, --dm-r-box
     for boxes you write several lines in, --dm-r-tag for tags. Where the browser smooths corners (corner-shape: squircle) a
     corner looks smaller, so each takes the larger -sq radius there to look the same size. Fields share one height and,
     where a component is a single field, one width */
  --dm-r-field:10px; --dm-r-field-sq:16px; --dm-r-box:14px; --dm-r-box-sq:22px; --dm-r-tag:7px; --dm-r-tag-sq:12px;
  --dm-field-h:40px; --dm-field-w:320px;
  --dm-sans:"Inter",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --dm-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --dm-ease:cubic-bezier(.22,1,.36,1); --dm-ease-io:cubic-bezier(.65,0,.35,1);
  --dm-t-fast:.22s; --dm-t:.45s; --dm-t-slow:.7s;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#363636;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#424242; --dm-line-strong:#808080; --dm-field-line-strong:#808080;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035),inset 0 1px 0 rgba(255,255,255,.05); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#3d8bff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616; --dm-seg-k-shadow:0 0 0 1px rgba(255,255,255,.06),0 1px 2px rgba(0,0,0,.35); --dm-tip-bg:#3d3d3b; --dm-tip-fg:var(--dm-fg); --dm-tip-ring:0 0 0 1px rgba(255,255,255,.12);
  --dm-ok:#4ee28a; --dm-ok-bg:rgba(34,214,110,.2); --dm-ok-mark:#4cbb17; --dm-warn:#ffc247; --dm-warn-bg:rgba(255,184,40,.2); --dm-warn-mark:#ffa940; --dm-bad:#ff8a8a; --dm-bad-bg:rgba(255,90,90,.14);
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#a0c5ff; --dm-pb-bg:rgba(90,150,255,.18); --dm-pl:#cbb9ff; --dm-pl-bg:rgba(155,125,255,.18); --dm-pm:#6ad9a7; --dm-pm-bg:rgba(70,205,150,.16); --dm-pp:#ffb57a; --dm-pp-bg:rgba(255,155,80,.17);
  --dm-pr:#ffadbb; --dm-pr-bg:rgba(255,105,130,.17); --dm-py:#f0cd5a; --dm-py-bg:rgba(240,200,60,.15); --dm-pk:#ffa8d4; --dm-pk-bg:rgba(255,100,175,.16); --dm-pt:#5fd8df; --dm-pt-bg:rgba(60,200,210,.16);
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.045),0 1px 2px rgba(0,0,0,.28),0 6px 14px -6px rgba(0,0,0,.36),0 20px 36px -14px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.06); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.12),0 2px 4px rgba(0,0,0,.3),0 12px 24px -8px rgba(0,0,0,.45),0 32px 56px -20px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.07); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); color-scheme:dark}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#363636;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#424242; --dm-line-strong:#808080; --dm-field-line-strong:#808080;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035),inset 0 1px 0 rgba(255,255,255,.05); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#3d8bff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616; --dm-seg-k-shadow:0 0 0 1px rgba(255,255,255,.06),0 1px 2px rgba(0,0,0,.35); --dm-tip-bg:#3d3d3b; --dm-tip-fg:var(--dm-fg); --dm-tip-ring:0 0 0 1px rgba(255,255,255,.12);
  --dm-ok:#4ee28a; --dm-ok-bg:rgba(34,214,110,.2); --dm-ok-mark:#4cbb17; --dm-warn:#ffc247; --dm-warn-bg:rgba(255,184,40,.2); --dm-warn-mark:#ffa940; --dm-bad:#ff8a8a; --dm-bad-bg:rgba(255,90,90,.14);
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#a0c5ff; --dm-pb-bg:rgba(90,150,255,.18); --dm-pl:#cbb9ff; --dm-pl-bg:rgba(155,125,255,.18); --dm-pm:#6ad9a7; --dm-pm-bg:rgba(70,205,150,.16); --dm-pp:#ffb57a; --dm-pp-bg:rgba(255,155,80,.17);
  --dm-pr:#ffadbb; --dm-pr-bg:rgba(255,105,130,.17); --dm-py:#f0cd5a; --dm-py-bg:rgba(240,200,60,.15); --dm-pk:#ffa8d4; --dm-pk-bg:rgba(255,100,175,.16); --dm-pt:#5fd8df; --dm-pt-bg:rgba(60,200,210,.16);
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.045),0 1px 2px rgba(0,0,0,.28),0 6px 14px -6px rgba(0,0,0,.36),0 20px 36px -14px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.06); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.12),0 2px 4px rgba(0,0,0,.3),0 12px 24px -8px rgba(0,0,0,.45),0 32px 56px -20px rgba(0,0,0,.55),inset 0 1px 0 rgba(255,255,255,.07); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); color-scheme:dark}

/* the accent's hover fill (--dm-accent-2) and tint (--dm-accent-bg) are worked out from the accent, in every style and theme, so a
   picked accent brings its own. Hovering a filled button moves its fill away from its text colour: darker under white text,
   lighter under dark text, so the label keeps its contrast in every style, theme and accent */
:root,[data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 9%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}
@supports (color:rgb(from red r g b)){:root,[data-style="soft"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,rgb(from var(--dm-on-accent) calc(255 - r) calc(255 - g) calc(255 - b)))}}
@supports not (color:rgb(from red r g b)){:root,[data-style="soft"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000)}:root:not([data-style="soft"]),:root:not([data-style="soft"]):not([data-theme="light"]),:root:not([data-style="soft"])[data-theme="dark"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#fff)}}
/* picked things (chips, options, cards in a picker) are white tiles with a dimmed grey edge, and the picked one's edge
   is a light step stronger, never a dark or black outline */
:root,[data-style="soft"]{--dm-pick-line:var(--dm-rail);--dm-pick-on:var(--dm-faint)}

/* Soft is plush: corners are drawn as squircles where the browser can (corner-shape), and since a squircle's corner
   reads smaller than a round one of the same radius, the radii grow with it. Circles (spinners, loader rings, avatars,
   dots) stay round; pills, chips, buttons and switchers are squircles too. Blueprint stays square (its corners are 0) */
@supports (corner-shape:squircle){
:root,[data-style="soft"]{--dm-rk:1.7}
:root:not([data-style="soft"]){--dm-rk:1}
:where([data-dm]) *,:where([data-dm]) *::before,:where([data-dm]) *::after{corner-shape:squircle}
.dm-acx-n .dm-s,.dm-afx-pen,.dm-afx-r b,.dm-agx-now i,.dm-alg-ph-pg,.dm-alg-sc-knob,.dm-alg-sc-ld,.dm-alg-sc-n,.dm-aln-cw-tr b,.dm-aln-pk,.dm-asx-lp-stop,.dm-asx-lp-th,.dm-asx-lp-th i,.dm-asx-tb-dot,.dm-atx-cmp-ok,.dm-atx-cmp-send,.dm-atx-cmp-x,.dm-av,.dm-bdg-dot,.dm-bdg-x,.dm-bdg-x:focus-visible,.dm-btx-live,.dm-bws-dots i,.dm-ccx-fl .dm-flag,.dm-ccx-sw,.dm-cmx-go,.dm-cmx-pin,.dm-cpx-att .dm-fchip .dm-rt,.dm-cpx-att .dm-fchip .dm-x,.dm-cpx-dot,.dm-cpx-send,.dm-ctb-n .dm-s,.dm-dot,.dm-drv-ag,.dm-drv-ring,.dm-dtx-sl .dm-k,.dm-ecx-days b,.dm-ecx-dh.dm-t b,.dm-erx-o i,.dm-evr-dot,.dm-evr-jg-arc .dm-tr,.dm-evr-jg-arc i,.dm-fxp-n .dm-ag,.dm-hox-av,.dm-ib,.dm-lcx-ring,.dm-lnx-k i,.dm-lnx-pt,.dm-mix-dot,.dm-msc-c button,.dm-ntx-n .dm-u,.dm-obx .dm-obx-rw .dm-obx-rk,.dm-obx-ck,.dm-obx-rk,.dm-plx-s .dm-n,.dm-psx-go,.dm-pulse,.dm-rq-wk-c .dm-rq-ic,.dm-rq-wk-ring .dm-h i,.dm-rq-wk-ring .dm-tr,.dm-rq-wk-stack i,.dm-rsu-g,.dm-rsu-rc-nd,.dm-rsu-rc-ok,.dm-rsu-rc-ok i,.dm-rsu-rp-ok,.dm-rxx-add,.dm-sgc-wr .dm-e i,.dm-spin,.dm-ssx-ics span,.dm-ste-go,.dm-stx-conf i.dm-d,.dm-stx-st .dm-n,.dm-tcx[data-d="inline"] .dm-tcb-wire i,.dm-think i,.dm-thp-send,.dm-thp[data-d] .dm-tpx-dots i,.dm-thp[data-d] .dm-tpx-send,.dm-thp[data-d] .dm-tpx-st,.dm-tk-st .dm-mk,.dm-tsk-c .dm-g,.dm-tst-t .dm-g,.dm-ttp-av,.dm-vcx-dot,.dm-vor .dm-vor-orb i,.dm-vor-dot,.dm-vor-gl,.dm-vor-orb i,.dm-cxm-av,.dm-crs-dots button,.dm-rdx-lg i,.dm-scx-lg i.dm-c,.dm-cvq-lg i.dm-c,.dm-rgx-r i,.dm-cpk-k,.dm-wsx-marks span,.dm-igx-steps i,.dm-ths-dg i,.dm-ths-mtx i,.dm-hsc-dot,.dm-hsc-pt i{corner-shape:round}
.dm-aln-det div::before{corner-shape:round}
.dm-asx-lp-rg::-moz-range-thumb{corner-shape:round}
.dm-asx-lp-rg::-webkit-slider-thumb{corner-shape:round}
.dm-btx-live::after{corner-shape:round}
.dm-dpk-d.dm-t::after{corner-shape:round}
.dm-ecx-now::before{corner-shape:round}
.dm-fxp-tree::-webkit-scrollbar-thumb{corner-shape:round}
.dm-hand::before{corner-shape:round}
.dm-hnx-t .dm-ic::after{corner-shape:round}
.dm-ksx-s .dm-ic::after{corner-shape:round}
.dm-pulse::after{corner-shape:round}
.dm-radar::after{corner-shape:round}
.dm-radar::before{corner-shape:round}
.dm-sgc-mo .dm-d.dm-e::after{corner-shape:round}
.dm-shx-r .dm-ic::after{corner-shape:round}
.dm-stx-ok::after{corner-shape:round}
.dm-tmx-body::-webkit-scrollbar-thumb{corner-shape:round}
