.dm-afx-desk::before{corner-shape:round}
}
/* ---------- page shell ---------- */
:where([data-dm]) *{box-sizing:border-box}
:where([data-dm]) button,:where([data-dm]) input,:where([data-dm]) textarea,:where([data-dm]) select{font:inherit;color:inherit}
:where([data-dm]) button{background:none;border:0;padding:0;cursor:pointer}
/* one weight for emphasis: medium, never bold */
:where([data-dm]) b,:where([data-dm]) strong{font-weight:500}
:where([data-dm]) :focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px;border-radius:calc(6px * var(--dm-rk))}
/* a field shows the focus with its own edge, which steps up to --dm-field-line-strong, so it never takes the ring as well */
:where([data-dm]) :focus-visible:is(input:not([type="checkbox"],[type="radio"],[type="range"],[type="file"],[type="button"],[type="submit"],[type="reset"]),textarea,select,[contenteditable]:not([contenteditable="false"])){outline:0}/* ---------- icons ---------- */
.dm-i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.dm-i.dm-s{width:14px;height:14px}.dm-i.dm-xs{width:12px;height:12px}.dm-i.dm-l{width:18px;height:18px}
.dm-brand{width:16px;height:16px;display:block;flex:none}
.dm-flag{width:20px;height:15px;border-radius:3px;object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

/* ---------- primitives ---------- */
.dm-mono{font-family:var(--dm-mono)}
.dm-sp{flex:1}
.dm-num{font-variant-numeric:tabular-nums}
.dm-muted{color:var(--dm-muted)}.dm-fg2{color:var(--dm-fg2)}
.dm-panel{background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);position:relative}
