  function fromImage(im: HTMLImageElement): RGB[] | null {
    const W = 96, H = 64, ox = canvas(W, H).getContext('2d'); if (!ox) return null;
    const fr = (cv.clientWidth / cv.clientHeight) || 1.5, ir = im.naturalWidth / im.naturalHeight;
