    const px: RGB[] = [];
    for (let j = 0; j < 32; j++) for (let i = 0; i < 48; i++) { const c = [0, 0, 0]; for (const [a, b] of [[0, 0], [1, 0], [0, 1], [1, 1]]) { const k = ((j * 2 + b) * W + i * 2 + a) * 4; c[0] += d[k]; c[1] += d[k + 1]; c[2] += d[k + 2]; } px.push(c.map(v => v / 4)); }
