      c.fillStyle = BAD; c.globalAlpha = .9 * cl(q * 2); for (const [i, j] of f.hot) c.fillRect(i * cw + 1, j * bh + 1, cw - 2, bh - 2);
    } else for (let n = 0; n < 24 * 16; n++) {
