      const i = n % 24, j = n / 24 | 0; c.globalAlpha = s; c.drawImage(f.grey, i * cw, j * bh, cw, bh, i * cw + cw * (1 - s) / 2, j * bh + bh * (1 - s) / 2, cw * s, bh * s);
