    if (!fit()) return;
    const l = LV[1], G = geo(l); x.setTransform(dpr, 0, 0, dpr, 0, 0); x.clearRect(0, 0, w, ht);
    for (let n = 0; n < l.css.length; n++) { x.fillStyle = l.css[n]; box(x, l, n, G); }
